-- Inline, exact binary fractions; every case is retained by the reference generator.
-- case: {"id": "coalesce", "ordered": true, "status": "ok"}
WITH t AS (
 SELECT 1 AS id, CAST('2.5' AS REAL) AS f, 2 AS qty, TRUE AS returned
 UNION ALL SELECT 2, CAST(NULL AS REAL), 3, FALSE
 UNION ALL SELECT 3, CAST('-3.5' AS REAL), 4, NULL
 UNION ALL SELECT 4, CAST('0' AS REAL), 5, TRUE
 UNION ALL SELECT 5, CAST('2.5' AS REAL), 6, FALSE
 UNION ALL SELECT 6, CAST(NULL AS REAL), 7, TRUE
)
SELECT id,COALESCE(f,0) AS x FROM t ORDER BY id;

