 UNION ALL SELECT 5, CAST('2.5' AS REAL), 6, FALSE
 UNION ALL SELECT 6, CAST(NULL AS REAL), 7, TRUE
)
SELECT id,COALESCE(f,-7) AS x FROM t ORDER BY id;

